window.PYQ_CS = {"version":1,"subject":"Computer Science","class":12,"chapters":[{"n":1,"t":"Python Revision Tour","unit":"I","unitName":"Computational Thinking and Programming – 2","unitMarks":40,"count":63},{"n":2,"t":"Functions","unit":"I","unitName":"Computational Thinking and Programming – 2","unitMarks":40,"count":11},{"n":3,"t":"Exception Handling","unit":"I","unitName":"Computational Thinking and Programming – 2","unitMarks":40,"count":4},{"n":4,"t":"File Handling","unit":"I","unitName":"Computational Thinking and Programming – 2","unitMarks":40,"count":12},{"n":5,"t":"Data Structures: Stack","unit":"I","unitName":"Computational Thinking and Programming – 2","unitMarks":40,"count":1},{"n":6,"t":"Computer Networks","unit":"II","unitName":"Computer Networks","unitMarks":10,"count":15},{"n":7,"t":"Database Concepts","unit":"III","unitName":"Database Management","unitMarks":20,"count":8},{"n":8,"t":"Structured Query Language (SQL)","unit":"III","unitName":"Database Management","unitMarks":20,"count":23},{"n":9,"t":"Interface of Python with MySQL","unit":"III","unitName":"Database Management","unitMarks":20,"count":2}],"questions":[{"id":"s0001","chapter":1,"type":"tf","text":"State True or False:\n\"Comments are not executed by interpreter.\"","options":{"A":"True","B":"False"},"answer":"A","hint":"What does the interpreter do on reaching a # line?","explanation":"Comments are ignored by the Python interpreter, so the statement is True.","difficulty":1,"sources":[[2023,"C","91",1]]},{"id":"s0002","chapter":1,"type":"mcq","text":"Which of the following is not a sequential datatype in Python ?","options":{"A":"Dictionary","B":"String","C":"List","D":"Tuple"},"answer":"A","hint":"Sequences are accessed by position index.","explanation":"Strings, lists and tuples are ordered sequences; a dictionary is a key-value mapping.","difficulty":1,"sources":[[2023,"C","91",2]]},{"id":"s0003","chapter":1,"type":"mcq","text":"Given the following dictionary\n```python\nDay={1:\"Monday\", 2: \"Tuesday\", 3: \"Wednesday\"}\n```\nWhich statement will return \"Tuesday\".","options":{"A":"`Day.pop()`","B":"`Day.pop(2)`","C":"`Day.pop(1)`","D":"`Day.pop(\"Tuesday\")`"},"answer":"B","hint":"pop() on a dictionary takes a key.","explanation":"`Day.pop(2)` removes the key 2 and returns its value \"Tuesday\".","difficulty":1,"sources":[[2023,"C","91",3]]},{"id":"s0004","chapter":1,"type":"mcq","text":"Consider the given expression :\n`7<4 or 6>3 and not 10==10 or 17>4`\nWhich of the following will be the correct output if the given expression is evaluated ?","options":{"A":"`True`","B":"`False`","C":"`NONE`","D":"`NULL`"},"answer":"A","hint":"Precedence: not, then and, then or.","explanation":"`6>3 and not 10==10` is False; so it is False or False or True, which is True.","difficulty":2,"sources":[[2023,"C","91",4]]},{"id":"s0005","chapter":1,"type":"mcq","text":"Select the correct output of the code :\n```python\nS=\"Amrit Mahotsav @ 75\"\nA=S.split(\" \",2)\nprint(A)\n```","options":{"A":"`('Amrit', 'Mahotsav', '@', '75')`","B":"`['Amrit', 'Mahotsav', '@ 75']`","C":"`('Amrit', 'Mahotsav', '@75')`","D":"`['Amrit', 'Mahotsav', '@', '75']`"},"answer":"B","hint":"The second argument limits the number of splits.","explanation":"maxsplit=2 gives only two splits, so the rest '@ 75' stays together in a list of 3 strings.","difficulty":2,"sources":[[2023,"C","91",5]]},{"id":"s0006","chapter":4,"type":"mcq","text":"Which of the following modes in Python creates a new file, if file does not exist and overwrites the content, if the file exists ?","options":{"A":"`r+`","B":"`r`","C":"`w`","D":"`a`"},"answer":"C","hint":"Which mode truncates an existing file?","explanation":"`w` creates the file if missing and overwrites it if present.","difficulty":1,"sources":[[2023,"C","91",6]]},{"id":"s0007","chapter":1,"type":"mcq","text":"Fill in the blank :\n___________ is not a valid built-in function for list manipulations.","options":{"A":"`count()`","B":"`length()`","C":"`append()`","D":"`extend()`"},"answer":"B","hint":"The length function has a shorter name.","explanation":"Lists have count(), append() and extend(); the length function is len(), so `length()` is invalid.","difficulty":1,"sources":[[2023,"C","91",7]]},{"id":"s0008","chapter":1,"type":"mcq","text":"Which of the following is an example of identity operators of Python ?","options":{"A":"`is`","B":"`on`","C":"`in`","D":"`not in`"},"answer":"A","hint":"Identity operators compare object identity.","explanation":"Python's identity operators are `is` and `is not`; `in`/`not in` are membership operators.","difficulty":1,"sources":[[2023,"C","91",8]]},{"id":"s0009","chapter":1,"type":"mcq","text":"Which of the following statement(s) would give an error after executing the following code ?\n```python\nS=\"Happy\"            # Statement 1\nprint(S*2)            # Statement 2\nS+=\"Independence\"    # Statement 3\nS.append(\"Day\")       # Statement 4\nprint(S)              # Statement 5\n```","options":{"A":"Statement 2","B":"Statement 3","C":"Statement 4","D":"Statement 3 and 4"},"answer":"C","hint":"Do strings have an append method?","explanation":"Strings have no append() method, so Statement 4 raises AttributeError; repetition and concatenation are valid.","difficulty":1,"sources":[[2023,"C","91",9]]},{"id":"s0010","chapter":7,"type":"mcq","text":"Fill in the blank :\nIn a relational model, tables are called _________, that store data for different columns.","options":{"A":"Attributes","B":"Degrees","C":"Relations","D":"Tuples"},"answer":"C","hint":"Rows are tuples, columns are attributes; what is the table itself?","explanation":"In the relational model a table is called a relation.","difficulty":1,"sources":[[2023,"C","91",10]]},{"id":"s0011","chapter":4,"type":"mcq","text":"The correct syntax of `tell()` is :","options":{"A":"`tell.file_object()`","B":"`file_object.tell()`","C":"`tell.file_object(1)`","D":"`file_object.tell(1)`"},"answer":"B","hint":"tell() is a method of the file object and takes no argument.","explanation":"`file_object.tell()` returns the current file position.","difficulty":1,"sources":[[2023,"C","91",11]]},{"id":"s0012","chapter":8,"type":"mcq","text":"Fill in the blank :\n_________ statement of SQL is used to insert new records in a table.","options":{"A":"`ALTER`","B":"`UPDATE`","C":"`INSERT`","D":"`CREATE`"},"answer":"C","hint":"Which DML command adds rows?","explanation":"`INSERT INTO` adds new records to a table.","difficulty":1,"sources":[[2023,"C","91",12]]},{"id":"s0013","chapter":6,"type":"mcq","text":"Fill in the blank :\nIn _________ switching, before a communication starts, a dedicated path is identified between the sender and the receiver.","options":{"A":"Packet","B":"Graph","C":"Circuit","D":"Plot"},"answer":"C","hint":"Think of the old telephone network.","explanation":"Circuit switching sets up a dedicated path before communication begins.","difficulty":1,"sources":[[2023,"C","91",13]]},{"id":"s0014","chapter":1,"type":"mcq","text":"What will the following expression be evaluated to in Python ?\n`print(6/3 + 4**3//8-4)`","options":{"A":"`6.5`","B":"`4.0`","C":"`6.0`","D":"`4`"},"answer":"C","hint":"Order: ** first, then / and // left to right, then + and -.","explanation":"6/3=2.0; 4**3=64, 64//8=8; 2.0+8-4 = 6.0.","difficulty":2,"sources":[[2023,"C","91",14]]},{"id":"s0015","chapter":1,"type":"mcq","text":"Which of the following functions is a valid built-in function for both list and dictionary datatype ?","options":{"A":"`items()`","B":"`len()`","C":"`update()`","D":"`values()`"},"answer":"B","hint":"Which one is a general built-in, not a method of one type?","explanation":"`len()` works on both lists and dictionaries; items(), update() and values() are dictionary-only.","difficulty":1,"sources":[[2023,"C","91",15]]},{"id":"s0016","chapter":9,"type":"mcq","text":"`fetchone()` method fetches only one row in a ResultSet and returns a __________.","options":{"A":"Tuple","B":"List","C":"Dictionary","D":"String"},"answer":"A","hint":"A row from MySQL connector comes back in a fixed, immutable form.","explanation":"`fetchone()` returns a single row as a tuple (or None if no rows remain).","difficulty":1,"sources":[[2023,"C","91",16]]},{"id":"s0017","chapter":5,"type":"ar","text":"Assertion (A): In Python, a stack can be implemented using a list.\nReason (R): A stack is an ordered linear list of elements that works on the principle of First In First Out (FIFO).","options":{"A":"Both (A) and (R) are true and (R) is the correct explanation for (A).","B":"Both (A) and (R) are true and (R) is not the correct explanation for (A).","C":"(A) is true but (R) is false.","D":"(A) is false but (R) is true."},"answer":"C","hint":"Recall the principle a stack follows.","explanation":"A is true (append/pop), but a stack works on LIFO, not FIFO, so R is false.","difficulty":1,"sources":[[2023,"C","91",17]]},{"id":"s0018","chapter":4,"type":"ar","text":"Assertion (A): readlines() reads all the lines from a text file and returns the lines along with newline as a list of strings.\nReason (R): readline() can read the entire text file line by line without using any looping statements.","options":{"A":"Both (A) and (R) are true and (R) is the correct explanation for (A).","B":"Both (A) and (R) are true and (R) is not the correct explanation for (A).","C":"(A) is true but (R) is false.","D":"(A) is false but (R) is true."},"answer":"C","hint":"How many lines does one readline() call return?","explanation":"A is true; R is false because readline() reads a single line per call, so a loop is needed to read the whole file.","difficulty":2,"sources":[[2023,"C","91",18]]},{"id":"s0019","chapter":1,"type":"tf","text":"State True or False:\n\"Identifiers are names used to identify a variable, function in a program\".","options":{"A":"True","B":"False"},"answer":"A","hint":"Think about what an identifier is used for.","explanation":"Identifiers are the names given to variables, functions, classes etc., so the statement is True.","difficulty":1,"sources":[[2023,"R","91",1]]},{"id":"s0020","chapter":1,"type":"mcq","text":"Which of the following is a valid keyword in Python ?","options":{"A":"false","B":"return","C":"non_local","D":"none"},"answer":"B","hint":"Python keywords are case-sensitive.","explanation":"`return` is a keyword; `False`, `nonlocal` and `None` need exact spelling/case, so the other options are not keywords.","difficulty":1,"sources":[[2023,"R","91",2]]},{"id":"s0021","chapter":1,"type":"mcq","text":"Given the following Tuple\n```python\nTup= (10, 20, 30, 50)\n```\nWhich of the following statements will result in an error ?","options":{"A":"`print(Tup[0])`","B":"`Tup.insert(2,3)`","C":"`print(Tup[1:2])`","D":"`print(len(Tup))`"},"answer":"B","hint":"Tuples are immutable.","explanation":"Tuples have no insert() method (they cannot be modified), so `Tup.insert(2,3)` raises AttributeError.","difficulty":1,"sources":[[2023,"R","91",3]]},{"id":"s0022","chapter":1,"type":"mcq","text":"Consider the given expression :\n`5<10 and 12>7 or not 7>4`\nWhich of the following will be the correct output, if the given expression is evaluated ?","options":{"A":"`True`","B":"`False`","C":"`NONE`","D":"`NULL`"},"answer":"A","hint":"and binds tighter than or; not binds tighter than and.","explanation":"`5<10 and 12>7` is True and `not 7>4` is False; True or False gives True.","difficulty":2,"sources":[[2023,"R","91",4]]},{"id":"s0023","chapter":4,"type":"mcq","text":"Which of the following mode keeps the file offset position at the end of the file ?","options":{"A":"`r+`","B":"`r`","C":"`w`","D":"`a`"},"answer":"D","hint":"Which mode is meant for adding data to the end?","explanation":"Append mode `a` places the file offset at the end of the file; r/r+ start at the beginning and w truncates the file.","difficulty":1,"sources":[[2023,"R","91",6]]},{"id":"s0024","chapter":1,"type":"mcq","text":"Fill in the blank.\n_____ function is used to arrange the elements of a list in ascending order.","options":{"A":"`sort()`","B":"`arrange()`","C":"`ascending()`","D":"`asort()`"},"answer":"A","hint":"It is a built-in list method.","explanation":"`list.sort()` sorts a list in ascending order by default.","difficulty":1,"sources":[[2023,"R","91",7]]},{"id":"s0025","chapter":7,"type":"mcq","text":"Fill in the blank.\n_____ is a number of tuples in a relation.","options":{"A":"Attribute","B":"Degree","C":"Domain","D":"Cardinality"},"answer":"D","hint":"Tuples are rows.","explanation":"Cardinality is the number of tuples (rows) in a relation; degree is the number of attributes.","difficulty":1,"sources":[[2023,"R","91",10]]},{"id":"s0026","chapter":4,"type":"mcq","text":"The syntax of seek() is :\n`file_object.seek(offset[, reference_point])`\nWhat is the default value of `reference_point` ?","options":{"A":"0","B":"1","C":"2","D":"3"},"answer":"A","hint":"Think of seeking from the start of the file.","explanation":"The default reference point is 0, i.e. the beginning of the file.","difficulty":1,"sources":[[2023,"R","91",11]]},{"id":"s0027","chapter":8,"type":"mcq","text":"Fill in the blank :\n_______ clause is used with SELECT statement to display data in a sorted form with respect to a specified column.","options":{"A":"`WHERE`","B":"`ORDER BY`","C":"`HAVING`","D":"`DISTINCT`"},"answer":"B","hint":"Which clause arranges rows?","explanation":"`ORDER BY` sorts the result rows by the given column(s).","difficulty":1,"sources":[[2023,"R","91",12]]},{"id":"s0028","chapter":1,"type":"mcq","text":"What will the following expression be evaluated to in Python ?\n`print(4+3*5/3-5%2)`","options":{"A":"`8.5`","B":"`8.0`","C":"`10.2`","D":"`10.0`"},"answer":"B","hint":"Evaluate *, /, % first (left to right), then + and -.","explanation":"3*5=15, 15/3=5.0, 5%2=1; so 4+5.0-1 = 8.0.","difficulty":2,"sources":[[2023,"R","91",14]]},{"id":"s0029","chapter":2,"type":"mcq","text":"Which function returns the sum of all elements of a list ?","options":{"A":"`count()`","B":"`sum()`","C":"`total()`","D":"`add()`"},"answer":"B","hint":"It is a built-in function for numeric iterables.","explanation":"The built-in `sum()` adds all elements of a list.","difficulty":1,"sources":[[2023,"R","91",15]]},{"id":"s0030","chapter":9,"type":"mcq","text":"fetchall() method fetches all rows in a result set and returns a :","options":{"A":"Tuple of lists","B":"List of tuples","C":"List of strings","D":"Tuple of strings"},"answer":"B","hint":"Each row is a tuple.","explanation":"`fetchall()` returns a list in which each row is a tuple.","difficulty":1,"sources":[[2023,"R","91",16]]},{"id":"s0031","chapter":2,"type":"ar","text":"Assertion (A): To use a function from a particular module, we need to import the module.\nReason (R): import statement can be written anywhere in the program, before using a function from that module.","options":{"A":"Both (A) and (R) are true and (R) is the correct explanation for (A).","B":"Both (A) and (R) are true and (R) is not the correct explanation for (A).","C":"(A) is true but (R) is false.","D":"(A) is false but (R) is true."},"answer":"B","hint":"Is the Reason about why import is needed, or about where it can be placed?","explanation":"Both statements are true, but R only says where import may appear; it does not explain why import is needed.","difficulty":2,"note":"Official answer B (CBSE gave half a mark for A).","sources":[[2023,"R","91",17]]},{"id":"s0032","chapter":1,"type":"tf","text":"State True or False:\n\"In Python, tuple is a mutable data type\".","options":{"A":"True","B":"False"},"answer":"B","hint":"Think about whether a tuple's items can be changed after creation.","explanation":"Tuples are immutable, so the statement is False.","difficulty":1,"sources":[[2024,"C","91/S",1]]},{"id":"s0033","chapter":7,"type":"mcq","text":"The primary key is selected from the set of ___________ .","options":{"A":"composite keys","B":"alternate keys","C":"candidate keys","D":"foreign keys"},"answer":"C","hint":"Which keys are eligible to become the primary key?","explanation":"Candidate keys are all columns that can uniquely identify rows; one is chosen as primary key.","difficulty":1,"sources":[[2024,"C","91/S",2]]},{"id":"s0034","chapter":1,"type":"mcq","text":"What will be the output of the following statement ?\n`print(6+5/4**2//5+8)`","options":{"A":"`-14.0`","B":"`14.0`","C":"`14`","D":"`-14`"},"answer":"B","hint":"Apply precedence: ** first, then / and // left to right, then +.","explanation":"4**2=16; 5/16=0.3125; 0.3125//5=0.0; 6+0.0+8=14.0.","difficulty":3,"sources":[[2024,"C","91/S",3]]},{"id":"s0035","chapter":1,"type":"mcq","text":"Select the correct output of the code :\n```python\nS = \"text#next\"\nprint(S.strip(\"t\"))\n```","options":{"A":"`ext#nex`","B":"`ex#nex`","C":"`text#nex`","D":"`ext#next`"},"answer":"A","hint":"strip() removes the given characters only from both ends.","explanation":"Leading 't' and trailing 't' are removed; the inner 't's stay, giving ext#nex.","difficulty":2,"sources":[[2024,"C","91/S",4]]},{"id":"s0036","chapter":8,"type":"mcq","text":"In SQL, which command will be used to add a new record in a table ?","options":{"A":"`UPDATE`","B":"`ADD`","C":"`INSERT`","D":"`ALTER TABLE`"},"answer":"C","hint":"Which DML command creates new rows?","explanation":"INSERT INTO adds a new record to a table.","difficulty":1,"sources":[[2024,"C","91/S",5]]},{"id":"s0037","chapter":6,"type":"mcq","text":"'L' in HTML stands for :","options":{"A":"Large","B":"Language","C":"Long","D":"Laser"},"answer":"B","hint":"HTML is a markup ___.","explanation":"HTML stands for HyperText Markup Language.","difficulty":1,"sources":[[2024,"C","91/S",6]]},{"id":"s0038","chapter":1,"type":"mcq","text":"Identify the valid Python identifier from the following :","options":{"A":"`2user`","B":"`user@2`","C":"`user_2`","D":"`user 2`"},"answer":"C","hint":"Identifiers cannot start with a digit or contain symbols/spaces other than underscore.","explanation":"Only user_2 starts with a letter and uses just letters, digits and underscore.","difficulty":1,"sources":[[2024,"C","91/S",7]]},{"id":"s0039","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options :\n```python\nGame=\"World Cup 2023\"\nprint(Game[-6::-1])\n```","options":{"A":"`CdrW`","B":"`ce o`","C":"`puC dlroW`","D":"`Error`"},"answer":"C","hint":"Index -6 is the start; step -1 walks backwards to the beginning.","explanation":"The string has 14 characters, so -6 is index 8 ('p'); reading backwards gives 'puC dlroW'.","difficulty":3,"sources":[[2024,"C","91/S",8]]},{"id":"s0040","chapter":2,"type":"mcq","text":"Predict the output of the following Python statements :\n```python\n>>>import statistics as s\n>>>s.mode ([10, 20, 10, 30, 10, 20, 30])\n```","options":{"A":"`30`","B":"`20`","C":"`10`","D":"`18.57`"},"answer":"C","hint":"mode() returns the most frequent value.","explanation":"10 occurs three times, 20 and 30 twice each, so mode is 10.","difficulty":1,"sources":[[2024,"C","91/S",9]]},{"id":"s0041","chapter":2,"type":"mcq","text":"Which of the following output will never be obtained when the given code is executed ?\n```python\nimport random\nShuffle = random.randrange(10)+1\nDraw = 10*random.randrange(5)\nprint (\"Shuffle\", Shuffle, end=\"#\")\nprint (\"Draw\", Draw)\n```","options":{"A":"`Shuffle 1 # Draw 0`","B":"`Shuffle 10 # Draw 10`","C":"`Shuffle 10 # Draw 0`","D":"`Shuffle 11 # Draw 50`"},"answer":"D","hint":"Work out the ranges of randrange(10)+1 and 10*randrange(5).","explanation":"Shuffle is 1 to 10 and Draw is one of 0,10,20,30,40; Shuffle 11 and Draw 50 are both impossible.","difficulty":2,"sources":[[2024,"C","91/S",10]]},{"id":"s0042","chapter":6,"type":"mcq","text":"Ethernet card is also known as :","options":{"A":"LIC","B":"MIC","C":"NIC","D":"OIC"},"answer":"C","hint":"The card connects a computer to a network.","explanation":"Ethernet card is called a Network Interface Card (NIC).","difficulty":1,"sources":[[2024,"C","91/S",11]]},{"id":"s0043","chapter":1,"type":"mcq","text":"For the following Python statement :\n`N = (25)`\nWhat shall be the type of N ?","options":{"A":"Integer","B":"String","C":"Tuple","D":"List"},"answer":"A","hint":"What makes a parenthesised value a tuple?","explanation":"Without a trailing comma the parentheses only group, so N is the int 25.","difficulty":1,"sources":[[2024,"C","91/S",13]]},{"id":"s0044","chapter":8,"type":"mcq","text":"Mr. Ravi is creating a field that contains alphanumeric values and fixed lengths. Which MySQL data type should he choose for the same ?","options":{"A":"`VARCHAR`","B":"`CHAR`","C":"`LONG`","D":"`NUMBER`"},"answer":"B","hint":"Fixed length versus variable length text types.","explanation":"CHAR stores fixed-length strings; VARCHAR is variable-length.","difficulty":1,"sources":[[2024,"C","91/S",14]]},{"id":"s0045","chapter":4,"type":"mcq","text":"__________ files are stored in a computer in a sequence of bytes.","options":{"A":"Text","B":"Binary","C":"CSV","D":"Notepad"},"answer":"B","hint":"Which file type is raw bytes rather than character lines?","explanation":"Binary files store data as a sequence of bytes.","difficulty":1,"sources":[[2024,"C","91/S",16]]},{"id":"s0046","chapter":2,"type":"ar","text":"Assertion (A): Global variables are accessible in the whole program.\nReason (R): Local variables are accessible only within a function or block in which it is declared.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Both statements are true; does R explain why globals are global?","explanation":"Both are true, but the local-variable scope does not explain the global-variable scope.","difficulty":2,"sources":[[2024,"C","91/S",17]]},{"id":"s0047","chapter":2,"type":"tf","text":"State True or False:\nWhile defining a function in Python, the positional parameters in the function header must always be written after the default parameters.","options":{"A":"True","B":"False"},"answer":"B","hint":"Recall the order of parameters in a def header.","explanation":"Positional (non-default) parameters must come before default parameters, so the statement is False.","difficulty":1,"sources":[[2024,"R","91",1]]},{"id":"s0048","chapter":8,"type":"mcq","text":"The `SELECT` statement when combined with _________ clause, returns records without repetition.","options":{"A":"`DISTINCT`","B":"`DESCRIBE`","C":"`UNIQUE`","D":"`NULL`"},"answer":"A","hint":"Which keyword removes duplicates?","explanation":"`SELECT DISTINCT` removes duplicate rows from the result.","difficulty":1,"sources":[[2024,"R","91",2]]},{"id":"s0049","chapter":1,"type":"mcq","text":"What will be the output of the following statement :\n`print(16*5/4*2/5-8)`","options":{"A":"`-3.33`","B":"`6.0`","C":"`0.0`","D":"`-13.33`"},"answer":"C","hint":"* and / have equal precedence; evaluate left to right.","explanation":"16*5=80; 80/4=20.0; 20.0*2=40.0; 40.0/5=8.0; 8.0-8 = 0.0.","difficulty":2,"sources":[[2024,"R","91",3]]},{"id":"s0050","chapter":2,"type":"mcq","text":"What possible output from the given options is expected to be displayed when the following Python code is executed ?\n```python\nimport random\nSignal = ['RED', 'YELLOW', 'GREEN']\nfor K in range(2, 0, -1):\n    R = random.randrange(K)\n    print(Signal[R], end = '#')\n```","options":{"A":"`YELLOW # RED #`","B":"`RED # GREEN #`","C":"`GREEN # RED #`","D":"`YELLOW # GREEN #`"},"answer":"A","hint":"List the values K takes and the range of randrange(K) for each.","explanation":"K takes 2 then 1. randrange(2) gives 0 or 1 (RED or YELLOW); randrange(1) always gives 0 (RED). So the output ends with RED#, and the first is RED or YELLOW.","difficulty":3,"note":"The paper prints spaces around # in the options; the code prints YELLOW#RED#.","sources":[[2024,"R","91",4]]},{"id":"s0051","chapter":8,"type":"mcq","text":"In SQL, the aggregate function which will display the cardinality of the table is _________.","options":{"A":"`sum()`","B":"`count(*)`","C":"`avg()`","D":"`sum(*)`"},"answer":"B","hint":"Cardinality means number of rows.","explanation":"`count(*)` counts all rows, i.e. the cardinality of the table.","difficulty":1,"sources":[[2024,"R","91",5]]},{"id":"s0052","chapter":6,"type":"mcq","text":"Which protocol out of the following is used to send and receive emails over a computer network ?","options":{"A":"PPP","B":"HTTP","C":"FTP","D":"SMTP"},"answer":"D","hint":"It has 'Mail' in its name.","explanation":"SMTP (Simple Mail Transfer Protocol) is used for email transfer.","difficulty":1,"sources":[[2024,"R","91",6]]},{"id":"s0053","chapter":1,"type":"mcq","text":"Identify the invalid Python statement from the following :","options":{"A":"`d = dict()`","B":"`e = {}`","C":"`f = []`","D":"`g = dict{}`"},"answer":"D","hint":"dict is called like a function, with parentheses.","explanation":"`dict{}` is a syntax error; `dict()` and `{}` create empty dictionaries and `[]` an empty list.","difficulty":1,"sources":[[2024,"R","91",7]]},{"id":"s0054","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options :\n```python\nmyStr=\"MISSISSIPPI\"\nprint(myStr[:4]+\"#\"+myStr[-5:])\n```","options":{"A":"`MISSI#SIPPI`","B":"`MISS#SIPPI`","C":"`MISS#IPPIS`","D":"`MISSI#IPPIS`"},"answer":"B","hint":"Count characters from the start for [:4] and from the end for [-5:].","explanation":"myStr[:4] is 'MISS' and myStr[-5:] is 'SIPPI', giving MISS#SIPPI.","difficulty":2,"sources":[[2024,"R","91",8]]},{"id":"s0055","chapter":1,"type":"mcq","text":"Identify the statement from the following which will raise an error :","options":{"A":"`print(\"A\"*3)`","B":"`print(5*3)`","C":"`print(\"15\" + 3)`","D":"`print(\"15\" + \"13\")`"},"answer":"C","hint":"Can a string be added to an int?","explanation":"`\"15\" + 3` mixes str and int, raising TypeError; the others print AAA, 15 and 1513.","difficulty":1,"sources":[[2024,"R","91",9]]},{"id":"s0056","chapter":1,"type":"mcq","text":"Select the correct output of the following code :\n```python\nevent=\"G20 Presidency@2023\"\nL=event.split(' ')\nprint(L[::-2])\n```","options":{"A":"`'G20'`","B":"`['Presidency@2023']`","C":"`['G20']`","D":"`'Presidency@2023'`"},"answer":"B","hint":"split() gives a list; a negative step starts from the last element.","explanation":"L = ['G20', 'Presidency@2023']; L[::-2] starts at the last element and steps back by 2, giving ['Presidency@2023'].","difficulty":2,"sources":[[2024,"R","91",10]]},{"id":"s0057","chapter":6,"type":"mcq","text":"Which of the following options is the correct unit of measurement for network bandwidth ?","options":{"A":"`KB`","B":"`Bit`","C":"`Hz`","D":"`Km`"},"answer":"C","hint":"Bandwidth is a frequency range in analog terms.","explanation":"Bandwidth is measured in Hertz (Hz) per the official answer (also in bps for data rate).","difficulty":1,"note":"Official answer: Hz (bandwidth of a channel).","sources":[[2024,"R","91",11]]},{"id":"s0058","chapter":2,"type":"mcq","text":"Observe the given Python code carefully :\n```python\na=20\ndef convert(a):\n    b=20\n    a=a+b\n\nconvert(10)\nprint(a)\n```\nSelect the correct output from the given options :","options":{"A":"`10`","B":"`20`","C":"`30`","D":"`Error`"},"answer":"B","hint":"Is the global a changed by the function?","explanation":"Inside convert, a is a local parameter (10) so a becomes 30 locally only; the global a stays 20, so print(a) shows 20.","difficulty":2,"sources":[[2024,"R","91",12]]},{"id":"s0059","chapter":3,"type":"tf","text":"State True or False:\nWhile handling exceptions in Python, name of the exception has to be compulsorily added with except clause.","options":{"A":"True","B":"False"},"answer":"B","hint":"Can a bare except be used?","explanation":"A plain `except:` without an exception name is allowed, so the statement is False.","difficulty":1,"sources":[[2024,"R","91",13]]},{"id":"s0060","chapter":8,"type":"mcq","text":"Which of the following is not a DDL command in SQL ?","options":{"A":"`DROP`","B":"`CREATE`","C":"`UPDATE`","D":"`ALTER`"},"answer":"C","hint":"DDL defines structure; the odd one manipulates data.","explanation":"UPDATE is a DML command; DROP, CREATE and ALTER are DDL.","difficulty":1,"sources":[[2024,"R","91",14]]},{"id":"s0061","chapter":4,"type":"mcq","text":"Consider the following Python statement :\n```python\nF=open('CONTENT.TXT')\n```\nWhich of the following is an invalid statement in Python ?","options":{"A":"`F.seek(1,0)`","B":"`F.seek(0,1)`","C":"`F.seek(0,-1)`","D":"`F.seek(0,2)`"},"answer":"C","hint":"Valid reference points are limited to a few values.","explanation":"The reference point (whence) must be 0, 1 or 2, so `F.seek(0,-1)` is invalid.","difficulty":2,"sources":[[2024,"R","91",16]]},{"id":"s0062","chapter":4,"type":"ar","text":"Assertion (A): CSV file is a human readable text file where each line has a number of fields, separated by comma or some other delimiter.\nReason (R): `writerow()` method is used to write a single row in a CSV file.","options":{"A":"Both (A) and (R) are true and (R) is the correct explanation for (A).","B":"Both (A) and (R) are true and (R) is not the correct explanation for (A).","C":"(A) is true but (R) is false.","D":"(A) is false but (R) is true."},"answer":"B","hint":"Does the Reason define what a CSV file is?","explanation":"Both statements are true, but writerow() describes writing a row and does not explain what a CSV file is.","difficulty":2,"sources":[[2024,"R","91",17]]},{"id":"s0063","chapter":1,"type":"ar","text":"Assertion (A): The expression \"Hello\".sort() in Python will give an error.\nReason (R): `sort()` does not exist as a method/function for strings in Python.","options":{"A":"Both (A) and (R) are true and (R) is the correct explanation for (A).","B":"Both (A) and (R) are true and (R) is not the correct explanation for (A).","C":"(A) is true but (R) is false.","D":"(A) is false but (R) is true."},"answer":"A","hint":"Why would calling sort on a string fail?","explanation":"Strings have no sort() method, so the call raises AttributeError, which is exactly why A is true.","difficulty":2,"sources":[[2024,"R","91",18]]},{"id":"s0064","chapter":1,"type":"tf","text":"State True or False:\nIf T is a tuple and L is a list, then `T+L` is a valid statement in Python.","options":{"A":"True","B":"False"},"answer":"B","hint":"Can you concatenate different sequence types?","explanation":"Tuple + list raises TypeError, so False.","difficulty":1,"sources":[[2025,"C","91/S",1]]},{"id":"s0065","chapter":1,"type":"mcq","text":"Identify the output of the following code segment :\n```python\ns = \"an apple. a toy.\"\ns=s.find('a',2)\nprint(s)\n```","options":{"A":"`0`","B":"`1`","C":"`3`","D":"`'a'`"},"answer":"C","hint":"find(sub, start) returns an index, searching from start.","explanation":"Searching from index 2, the first 'a' is at index 3 (\"an apple\": a,n,space,a).","difficulty":2,"sources":[[2025,"C","91/S",2]]},{"id":"s0066","chapter":1,"type":"mcq","text":"What is the value of the following expression ?\n`3 + 3.00, 3**3.0`","options":{"A":"`[6.0, 27.0]`","B":"`(6.0, 9.0)`","C":"`(6, 27)`","D":"`(6.0, 27.0)`"},"answer":"D","hint":"A comma-separated expression makes a tuple; float arithmetic gives floats.","explanation":"3+3.00=6.0 and 3**3.0=27.0, forming the tuple (6.0, 27.0).","difficulty":2,"sources":[[2025,"C","91/S",3]]},{"id":"s0067","chapter":1,"type":"mcq","text":"What is the output of the following expression ?\n```python\nSports=\"Paralympic Games\"\nprint (Sports.split(\"m\"))\n```","options":{"A":"`['Paraly','m','pic Ga','m','es']`","B":"`('Paraly','m','pic Games')`","C":"`('Paraly','pic Ga','es')`","D":"`['Paraly','pic Ga','es']`"},"answer":"D","hint":"split() returns a list and drops the separator.","explanation":"Splitting at each 'm' gives the list ['Paraly', 'pic Ga', 'es'].","difficulty":1,"sources":[[2025,"C","91/S",4]]},{"id":"s0068","chapter":1,"type":"mcq","text":"Which of the following is a mapped data type ?","options":{"A":"List","B":"Sets","C":"Dictionary","D":"Boolean"},"answer":"C","hint":"Mapping types store key-value pairs.","explanation":"Dictionary maps keys to values.","difficulty":1,"sources":[[2025,"C","91/S",6]]},{"id":"s0069","chapter":1,"type":"mcq","text":"If the dictionary D1 is defined as :\n`D1={1:'a',2:'b'}`\nthen which of the following statements is incorrect and hence will result in an error ?","options":{"A":"`D1.get(1)`","B":"`D1.get(3)`","C":"`D1.del(1)`","D":"`D1.clear()`"},"answer":"C","hint":"Check which method names actually exist for dicts.","explanation":"dict has no del() method (del is a keyword/statement); get(3) just returns None.","difficulty":1,"sources":[[2025,"C","91/S",7]]},{"id":"s0070","chapter":1,"type":"mcq","text":"Which of the following list methods accepts exactly 2 parameters ?","options":{"A":"`append()`","B":"`extend()`","C":"`insert()`","D":"`pop()`"},"answer":"C","hint":"One method takes an index and a value.","explanation":"insert(index, value) takes two arguments; the others take one or an optional one.","difficulty":1,"sources":[[2025,"C","91/S",8]]},{"id":"s0071","chapter":4,"type":"mcq","text":"A text file song.txt contains the following contents in it :\nLife goes on as it never ends\nWhat will be the output of the following code snippet ?\n```python\nf1=open(\"song.txt\",\"r\")\ns1=f1.read(5)\ns2=f1.readline(4)\ns3=f1.read(3)\nprint(s1,s3,sep=\"#\")\n```","options":{"A":"`goes# on`","B":"`Life #goes# on`","C":"`Life # on`","D":"`Error`"},"answer":"C","hint":"Track the file pointer: each call continues where the last stopped.","explanation":"read(5)='Life ', readline(4)='goes', read(3)=' on'; printing s1 and s3 with '#' gives 'Life # on'.","difficulty":3,"sources":[[2025,"C","91/S",10]]},{"id":"s0072","chapter":1,"type":"tf","text":"State True or False:\nIn Python, the `print()` evaluates the expression before displaying it on the screen.","options":{"A":"True","B":"False"},"answer":"A","hint":"What happens to print(2+3)?","explanation":"print() receives the evaluated value of the expression, so True.","difficulty":1,"sources":[[2025,"C","91/S",11]]},{"id":"s0073","chapter":2,"type":"mcq","text":"What will be the output of the following code segment ?\n```python\na=5\ndef func_1(b=10):\n    global a\n    a=b-10\n    b+=a\n    print(a,b)\nfunc_1(a)\n```","options":{"A":"`0 5`","B":"`5 0`","C":"`0 -5`","D":"`-5 0`"},"answer":"D","hint":"func_1(a) passes 5, so the default is ignored; a is global.","explanation":"b=5; a=5-10=-5 (global); b=5+(-5)=0; prints -5 0.","difficulty":2,"sources":[[2025,"C","91/S",12]]},{"id":"s0074","chapter":8,"type":"mcq","text":"Which of the following is not a valid relational operator used with WHERE clause in SQL ?","options":{"A":"`>`","B":"`<=`","C":"`=>`","D":"`<>`"},"answer":"C","hint":"Greater-or-equal is written with > first.","explanation":"The correct operator is >=; => is invalid.","difficulty":1,"sources":[[2025,"C","91/S",14]]},{"id":"s0075","chapter":8,"type":"mcq","text":"What is the default format of date in MySQL ?","options":{"A":"DD-MM-YYYY","B":"MM-DD-YYYY","C":"YYYY-MM-DD","D":"YYYY-DD-MM"},"answer":"C","hint":"Largest unit first.","explanation":"MySQL's default date format is YYYY-MM-DD.","difficulty":1,"sources":[[2025,"C","91/S",15]]},{"id":"s0076","chapter":8,"type":"mcq","text":"Ginni has created a table, SCORES in MySQL to store runs scored by players in a cricket match. The table contains the following records :\n\nTable : Scores\n```\nPLAYER    SCORE\nRanveer      50\nSukesh       35\nMirza        10\nJohn         51\nMurugan      70\n```\nWhich of the following statements will give 10 as output ?","options":{"A":"`SELECT MAX(Score) FROM Scores;`","B":"`SELECT MIN(Score) FROM Scores;`","C":"`SELECT SUM(Score) FROM Scores;`","D":"`SELECT AVG(Score) FROM Scores;`"},"answer":"B","hint":"Which aggregate gives the smallest value?","explanation":"The smallest score is 10 (Mirza), returned by MIN(Score); the other functions give 70, 216 and 43.2.","difficulty":1,"sources":[[2025,"C","91/S",16]]},{"id":"s0077","chapter":6,"type":"mcq","text":"Which of the following devices is essential to set up a wired LAN ?","options":{"A":"Modem","B":"NIC","C":"Repeater","D":"Firewall"},"answer":"B","hint":"Every computer needs a card to attach to the cable.","explanation":"A Network Interface Card is required in each device to connect to a wired LAN.","difficulty":1,"sources":[[2025,"C","91/S",17]]},{"id":"s0078","chapter":6,"type":"mcq","text":"Which network device serves as the entry and exit point of a network, as all the data coming in or going out of a network must first pass through it ?","options":{"A":"Modem","B":"Gateway","C":"Switch","D":"Repeater"},"answer":"B","hint":"The device that connects one network to another.","explanation":"A gateway is the entry/exit point through which all traffic passes.","difficulty":1,"sources":[[2025,"C","91/S",18]]},{"id":"s0079","chapter":6,"type":"mcq","text":"Which of the following IP addresses is valid ?","options":{"A":"`122.94.96.212`","B":"`212.254.258.210`","C":"`210.10.12.156.209`","D":"`122.294.56.68`"},"answer":"A","hint":"IPv4 has four octets, each 0-255.","explanation":"B and D have an octet above 255 and C has five octets; only A is valid.","difficulty":1,"sources":[[2025,"C","91/S",19]]},{"id":"s0080","chapter":1,"type":"ar","text":"Assertion (A): Every object in Python is assigned a unique identity (ID).\nReason (R): ID remains the same for the lifetime of that object.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Does a constant ID explain why the identity is unique?","explanation":"Both are true; an ID that stays fixed for the object's lifetime is what makes it a unique identity for it.","difficulty":2,"sources":[[2025,"C","91/S",20]]},{"id":"s0081","chapter":7,"type":"ar","text":"Assertion (A): Foreign key column of a table cannot have NULL entries.\nReason (R): Primary key column of a table cannot have NULL entries.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Can a foreign key hold NULL?","explanation":"A foreign key may contain NULL; only a primary key cannot, so A is false and R is true.","difficulty":2,"sources":[[2025,"C","91/S",21]]},{"id":"s0082","chapter":1,"type":"tf","text":"State True or False:\n\"A Python List must always contain all its elements of same data type.\"","options":{"A":"True","B":"False"},"answer":"B","hint":"Can a list hold an int and a string together?","explanation":"Lists are heterogeneous, so the statement is False.","difficulty":1,"sources":[[2025,"R","91",1]]},{"id":"s0083","chapter":1,"type":"mcq","text":"What will be the output of the following statement ?\n`print(14%3**2*4)`","options":{"A":"`16`","B":"`64`","C":"`20`","D":"`256`"},"answer":"C","hint":"** first; % and * have equal precedence, left to right.","explanation":"3**2=9; 14%9=5; 5*4=20.","difficulty":2,"sources":[[2025,"R","91",2]]},{"id":"s0084","chapter":1,"type":"mcq","text":"Identify the correct output of the following code snippet :\n```python\ngame=\"Olympic2024\"\nprint(game.index(\"C\"))\n```","options":{"A":"`0`","B":"`6`","C":"`-1`","D":"`ValueError`"},"answer":"D","hint":"Is 'C' (capital) present, and what does index() do when absent?","explanation":"Capital 'C' is not in the string (only lowercase 'c'), and index() raises ValueError.","difficulty":2,"sources":[[2025,"R","91",3]]},{"id":"s0085","chapter":1,"type":"mcq","text":"Which of the following is the correct identifier ?","options":{"A":"`global`","B":"`Break`","C":"`def`","D":"`with`"},"answer":"B","hint":"Three of these are Python keywords; Python is case-sensitive.","explanation":"global, def and with are keywords; Break (capital B) is not, so it is valid.","difficulty":1,"sources":[[2025,"R","91",4]]},{"id":"s0086","chapter":1,"type":"mcq","text":"Identify the invalid Python statement out of the following options :","options":{"A":"`print(\"A\",10,end=\"*\")`","B":"`print(\"A\",sep=\"*\",10)`","C":"`print(\"A\",10,sep=\"*\")`","D":"`print(\"A\"*10)`"},"answer":"B","hint":"Check the order of positional and keyword arguments.","explanation":"A positional argument (10) cannot follow a keyword argument (sep=...), so B is a SyntaxError.","difficulty":1,"sources":[[2025,"R","91",5]]},{"id":"s0087","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options :\n```python\nL=['TIC', 'TAC']\nprint(L[::-1])\n```","options":{"A":"`['CIT', 'CAT']`","B":"`['TIC', 'TAC']`","C":"`['CAT', 'CIT']`","D":"`['TAC', 'TIC']`"},"answer":"D","hint":"Slicing with step -1 reverses the list, not the strings.","explanation":"L[::-1] reverses the order of the elements only: ['TAC', 'TIC'].","difficulty":1,"sources":[[2025,"R","91",6]]},{"id":"s0088","chapter":1,"type":"mcq","text":"Which of the following operator evaluates to True if the variable on either side of the operator points towards the same memory location and False otherwise ?","options":{"A":"`is`","B":"`is not`","C":"`and`","D":"`or`"},"answer":"A","hint":"This is the identity operator.","explanation":"`is` compares object identity (same memory location).","difficulty":1,"sources":[[2025,"R","91",7]]},{"id":"s0089","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options :\n```python\nD={'S01':95, 'S02':96 }\nfor I in D :\n    print(I,end='#')\n```","options":{"A":"`S01#S02#`","B":"`95#96#`","C":"`S01,95#S02,96#`","D":"`S01#95#S02#96#`"},"answer":"A","hint":"Iterating over a dictionary gives its keys.","explanation":"The loop variable takes each key and prints it followed by '#': S01#S02#.","difficulty":1,"sources":[[2025,"R","91",8]]},{"id":"s0090","chapter":8,"type":"mcq","text":"While creating a table, which constraint does not allow insertion of duplicate values in the table ?","options":{"A":"`UNIQUE`","B":"`DISTINCT`","C":"`NOT NULL`","D":"`HAVING`"},"answer":"A","hint":"Which constraint enforces distinct values in a column?","explanation":"UNIQUE rejects duplicate values; DISTINCT is a query keyword, not a constraint.","difficulty":1,"sources":[[2025,"R","91",9]]},{"id":"s0091","chapter":2,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options :\n```python\ndef Change(N):\n    N=N+10\n    print(N,end='$$')\nN=15\nChange(N)\nprint(N)\n```","options":{"A":"`25$$15`","B":"`15$$25`","C":"`25$$25`","D":"`2525$$`"},"answer":"A","hint":"Local N inside the function is separate from the global N.","explanation":"Inside Change, local N becomes 25 and prints 25$$; global N stays 15, printed next.","difficulty":1,"sources":[[2025,"R","91",10]]},{"id":"s0092","chapter":3,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options :\n```python\nN='5'\ntry:\n    print('WORD' + N, end='#')\nexcept:\n    print('ERROR',end='#')\nfinally:\n    print('OVER')\n```","options":{"A":"`ERROR#`","B":"`WORD5#OVER`","C":"`WORD5#`","D":"`ERROR#OVER`"},"answer":"B","hint":"Is the concatenation valid, and does finally always run?","explanation":"'WORD' + '5' works, printing WORD5#; the finally block then prints OVER.","difficulty":1,"sources":[[2025,"R","91",11]]},{"id":"s0093","chapter":1,"type":"mcq","text":"Which of the following built-in function/method returns a dictionary ?","options":{"A":"`dict()`","B":"`keys()`","C":"`values()`","D":"`items()`"},"answer":"A","hint":"Which one constructs a dictionary rather than a view of one?","explanation":"dict() creates a dictionary; keys(), values() and items() return view objects.","difficulty":1,"sources":[[2025,"R","91",12]]},{"id":"s0094","chapter":8,"type":"mcq","text":"Which of the following is a DML command in SQL ?","options":{"A":"`UPDATE`","B":"`CREATE`","C":"`ALTER`","D":"`DROP`"},"answer":"A","hint":"DML manipulates data; DDL defines structure.","explanation":"UPDATE modifies data (DML); CREATE, ALTER and DROP are DDL.","difficulty":1,"sources":[[2025,"R","91",13]]},{"id":"s0095","chapter":8,"type":"mcq","text":"Which aggregate function in SQL displays the number of values in the specified column ignoring the NULL values ?","options":{"A":"`len()`","B":"`count()`","C":"`number()`","D":"`num()`"},"answer":"B","hint":"Which aggregate counts non-NULL entries?","explanation":"COUNT(column) counts non-NULL values in the column.","difficulty":1,"sources":[[2025,"R","91",14]]},{"id":"s0096","chapter":8,"type":"mcq","text":"In MYSQL, which type of value should not be enclosed within quotation marks ?","options":{"A":"`DATE`","B":"`VARCHAR`","C":"`FLOAT`","D":"`CHAR`"},"answer":"C","hint":"Numeric values are written bare.","explanation":"FLOAT values are numeric and unquoted; DATE, VARCHAR and CHAR values need quotes.","difficulty":1,"sources":[[2025,"R","91",15]]},{"id":"s0097","chapter":8,"type":"tf","text":"State True or False:\nIf table A has 6 rows and 3 columns, and table B has 5 rows and 2 columns, the Cartesian product of A and B will have 30 rows and 5 columns.","options":{"A":"True","B":"False"},"answer":"A","hint":"Rows multiply, columns add.","explanation":"Cartesian product has 6*5=30 rows and 3+2=5 columns, so True.","difficulty":1,"sources":[[2025,"R","91",16]]},{"id":"s0098","chapter":6,"type":"mcq","text":"Which of the following networking devices is used to regenerate and transmit the weakened signal ahead ?","options":{"A":"Hub","B":"Ethernet Card","C":"Repeater","D":"Modem"},"answer":"C","hint":"Which device amplifies/regenerates a fading signal?","explanation":"A repeater regenerates the weakened signal and retransmits it.","difficulty":1,"sources":[[2025,"R","91",17]]},{"id":"s0099","chapter":6,"type":"mcq","text":"Which of the following options is the correct protocol used for phone calls over the internet ?","options":{"A":"PPP","B":"FTP","C":"HTTP","D":"VoIP"},"answer":"D","hint":"Voice over Internet.","explanation":"VoIP (Voice over Internet Protocol) carries phone calls over the internet.","difficulty":1,"sources":[[2025,"R","91",18]]},{"id":"s0100","chapter":4,"type":"ar","text":"Assertion (A): For a binary file opened using 'rb' mode, the `pickle.dump()` method will display an error.\nReason (R): The `pickle.dump()` method is used to read from a binary file.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation for Assertion (A).","B":"Both Assertion (A) and Reason (R) are true and Reason (R) is not the correct explanation for Assertion (A).","C":"Assertion (A) is true but, Reason (R) is false.","D":"Assertion (A) is false but, Reason (R) is true."},"answer":"C","hint":"Which pickle method reads, and which writes?","explanation":"dump() writes, so using it on a file opened in 'rb' mode raises an error (A true); R is false because load() reads.","difficulty":2,"sources":[[2025,"R","91",20]]},{"id":"s0101","chapter":8,"type":"ar","text":"Assertion (A): We can retrieve records from more than one table in MYSQL.\nReason (R): Foreign key is used to establish a relationship between two tables.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation for Assertion (A).","B":"Both Assertion (A) and Reason (R) are true and Reason (R) is not the correct explanation for Assertion (A).","C":"Assertion (A) is true but, Reason (R) is false.","D":"Assertion (A) is false but, Reason (R) is true."},"answer":"B","hint":"Does the foreign key explain how multiple tables are queried?","explanation":"Both are true (joins retrieve from several tables), but a foreign key only links tables and is not the reason retrieval is possible.","difficulty":2,"sources":[[2025,"R","91",21]]},{"id":"s0102","chapter":1,"type":"mcq","text":"Which of the following is a keyword in Python?","options":{"A":"`Break`","B":"`None`","C":"`For`","D":"`Class`"},"answer":"B","hint":"Python keywords are case sensitive.","explanation":"None is a keyword; break, for, class are keywords only in lower case.","difficulty":1,"sources":[[2026,"C","91/7",1]]},{"id":"s0103","chapter":1,"type":"mcq","text":"What will be the output of the following statement?\n```python\nprint(18/3 == 18//3)\n```","options":{"A":"`0`","B":"`False`","C":"`1`","D":"`True`"},"answer":"D","hint":"Compare 6.0 with 6.","explanation":"18/3 = 6.0 and 18//3 = 6; 6.0 == 6 is True.","difficulty":1,"sources":[[2026,"C","91/7",2]]},{"id":"s0104","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options:\n```python\nD={\"A\":\"MUMBAI\", \"B\":\"CHENNAI\"}\nprint(\"C\" in D)\n```","options":{"A":"`False`","B":"`0`","C":"`True`","D":"`1`"},"answer":"A","hint":"The in operator checks dictionary keys.","explanation":"'C' is not a key of D, so the expression is False.","difficulty":1,"sources":[[2026,"C","91/7",3]]},{"id":"s0105","chapter":3,"type":"mcq","text":"What will be the output of the following Python code?\n```python\ntry:\n    num = 5\n    text = \"15\"\n    result = str(num) + text\n    print(result)\nexcept:\n    print(\"Error\")\n```","options":{"A":"`Error`","B":"`515`","C":"`20`","D":"`75`"},"answer":"B","hint":"Is str + str an error?","explanation":"str(5) is '5'; '5' + '15' concatenates to '515' with no exception.","difficulty":1,"sources":[[2026,"C","91/7",4]]},{"id":"s0106","chapter":1,"type":"mcq","text":"What will be the output of the following statement?\n```python\nprint(\"X\"* 2,\"Y\",end = 2 * \"X\", sep = \"#\")\n```","options":{"A":"`Error`","B":"`YY#XX`","C":"`XXYY#`","D":"`XX#YXX`"},"answer":"D","hint":"sep goes between items, end goes after the last.","explanation":"Items are 'XX' and 'Y' joined by '#', giving XX#Y, then end='XX' is appended: XX#YXX.","difficulty":2,"sources":[[2026,"C","91/7",5]]},{"id":"s0107","chapter":1,"type":"mcq","text":"If L is an empty list, then which of the following expressions are invalid?","options":{"A":"`L +'Hello'`","B":"`L + []`","C":"`L + [2]`","D":"`L * 2`"},"answer":"A","hint":"+ needs the same type on both sides for lists.","explanation":"A list cannot be concatenated with a string (TypeError); the others are valid.","difficulty":1,"sources":[[2026,"C","91/7",6]]},{"id":"s0108","chapter":1,"type":"mcq","text":"Which of the following statements will return the substring \"STR\" (i.e. the first 3 characters) from the string \"STRING\"?","options":{"A":"`\"STRING\"[:-3]`","B":"`\"STRING\"[-3::-1]`","C":"`\"STRING\"[3:]`","D":"`\"STRING\".startswith(3)`"},"answer":"A","hint":"Work out the end index of the slice.","explanation":"[:-3] stops 3 before the end, giving 'STR'. [-3::-1] gives 'IRTS' reversed part, [3:] gives 'ING', startswith(3) is an error.","difficulty":2,"sources":[[2026,"C","91/7",7]]},{"id":"s0109","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options:\n```python\nK=('A','B')\nV='TEST'\nD = dict.fromkeys(K, V)\nprint(D)\n```","options":{"A":"`{'A':'TEST', 'B': None}`","B":"`{'A': None, 'B':'TEST'}`","C":"`{'A':'TEST', 'B':'TEST'}`","D":"`Error`"},"answer":"C","hint":"fromkeys gives every key the same value.","explanation":"dict.fromkeys(K, V) creates a key for each element of K, all mapped to 'TEST'.","difficulty":2,"sources":[[2026,"C","91/7",8]]},{"id":"s0110","chapter":1,"type":"mcq","text":"Which of the following is true about clear() in Python?","options":{"A":"It deletes the dictionary itself with all its elements.","B":"It deletes all items of the dictionary resulting in an empty dictionary.","C":"If D is a dictionary, then `clear(D)` is the correct statement.","D":"No such function/method exists in Python."},"answer":"B","hint":"Does the dictionary still exist afterwards?","explanation":"D.clear() removes all items but keeps the (empty) dictionary object.","difficulty":1,"sources":[[2026,"C","91/7",9]]},{"id":"s0111","chapter":1,"type":"mcq","text":"Consider the statements given below and then choose the correct output from the given options:\n```python\nL = [\"A\", \"B\"]\nS=['C','D']\nL.extend(S)\nprint(L)\n```","options":{"A":"`['A', 'B', 'C', 'D']`","B":"`['A', 'B', 'CD']`","C":"`['A', 'B', ['CD']]`","D":"`['A', 'B', ['C','D']]`"},"answer":"A","hint":"extend adds each element separately.","explanation":"extend appends the elements of S one by one, giving ['A','B','C','D'].","difficulty":1,"sources":[[2026,"C","91/7",10]]},{"id":"s0112","chapter":4,"type":"mcq","text":"Which of the following options is the correct mode to open a binary pickled file to add more data in a previously existing binary pickled file?","options":{"A":"`'rb'`","B":"`'ab'`","C":"`'w'`","D":"`'r'`"},"answer":"B","hint":"Append, binary.","explanation":"'ab' opens a binary file for appending without erasing existing data.","difficulty":1,"sources":[[2026,"C","91/7",11]]},{"id":"s0113","chapter":8,"type":"tf","text":"State True or False:\nIn SQL, the UNIQUE constraint on an attribute ensures that values in it are not left empty.","options":{"A":"True","B":"False"},"answer":"B","hint":"Does UNIQUE forbid NULL?","explanation":"UNIQUE only prevents duplicates; NULLs are allowed. NOT NULL prevents empty values.","difficulty":1,"sources":[[2026,"C","91/7",12]]},{"id":"s0114","chapter":8,"type":"mcq","text":"The degree of the resulting relation after the Cartesian Product of two SQL tables with degrees A and B will be:","options":{"A":"A × B","B":"A + B","C":"A - B","D":"A / B"},"answer":"B","hint":"Degree counts columns; cardinality multiplies.","explanation":"Cartesian product combines the columns of both tables, so degree = A + B (cardinality would be the product).","difficulty":2,"sources":[[2026,"C","91/7",13]]},{"id":"s0115","chapter":8,"type":"mcq","text":"Which of the following is used to add a primary key to a column in a table created in MySQL?","options":{"A":"`INSERT`","B":"`MODIFY`","C":"`UPDATE`","D":"`ALTER`"},"answer":"D","hint":"This changes the table structure.","explanation":"ALTER TABLE ... ADD PRIMARY KEY changes the table structure; INSERT and UPDATE only change data.","difficulty":1,"sources":[[2026,"C","91/7",15]]},{"id":"s0116","chapter":8,"type":"mcq","text":"In MySQL, which of the following operator is used with WHERE clause and returns a True if the value belongs to the set of specified values?","options":{"A":"`DISTINCT`","B":"`IN`","C":"`LIKE`","D":"`NOT`"},"answer":"B","hint":"Membership in a set of values.","explanation":"IN tests whether a value matches any value in a list.","difficulty":1,"sources":[[2026,"C","91/7",16]]},{"id":"s0117","chapter":6,"type":"mcq","text":"Which of the following networking medium is uni-directional and most appropriate to be used for long distance wireless communication?","options":{"A":"Radio waves","B":"Infrared","C":"Bluetooth","D":"Microwaves"},"answer":"D","hint":"Line-of-sight, point-to-point, long distance.","explanation":"Microwaves are uni-directional (line of sight) and suited for long-distance wireless links.","difficulty":1,"sources":[[2026,"C","91/7",17]]},{"id":"s0118","chapter":6,"type":"mcq","text":"Which of the following is the correct protocol used for accessing a Web page?","options":{"A":"HTTP","B":"FTP","C":"VoIP","D":"SMTP"},"answer":"A","hint":"The protocol seen at the start of a web URL.","explanation":"HTTP (HyperText Transfer Protocol) is used to access web pages.","difficulty":1,"sources":[[2026,"C","91/7",18]]},{"id":"s0119","chapter":6,"type":"mcq","text":"Which of the following options is true about XML?","options":{"A":"It stands for Expert Manipulating Language.","B":"It is a programming language.","C":"It is a dynamic language used to store and transport data through web pages.","D":"It is same as HTML."},"answer":"C","hint":"XML is about describing and carrying data.","explanation":"XML stands for eXtensible Markup Language and is used to store and transport data; the other options are wrong.","difficulty":1,"sources":[[2026,"C","91/7",19]]},{"id":"s0120","chapter":1,"type":"ar","text":"Assertion (A): The upper() function/method in Python returns the string with all lowercase letters of the given string converted to uppercase.\nReason (R): Strings are mutable objects in Python.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Can a string be changed in place?","explanation":"upper() returns a new upper-case string (A true), but strings are immutable (R false).","difficulty":1,"sources":[[2026,"C","91/7",20]]},{"id":"s0121","chapter":7,"type":"ar","text":"Assertion (A): If we define an attribute of a table as a Foreign key, then UNIQUE and NOT NULL constraints are automatically applied to it.\nReason (R): The Foreign key column of a table takes its values from the Primary key of another table.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Can a foreign key repeat or be NULL?","explanation":"A is false: a foreign key may contain duplicates and NULLs. R is true: it references the primary key of another table.","difficulty":2,"sources":[[2026,"C","91/7",21]]},{"id":"s0122","chapter":1,"type":"tf","text":"State True or False:\nIn Python, data type of 74 is same as the data type of 74.0.","options":{"A":"True","B":"False"},"answer":"B","hint":"Compare int and float.","explanation":"74 is an int while 74.0 is a float, so the types differ.","difficulty":1,"sources":[[2026,"R","91",1]]},{"id":"s0123","chapter":1,"type":"mcq","text":"Identify the output of the following code snippet:\n```python\ns = \"the Truth\"\nprint(s.capitalize())\n```","options":{"A":"`The truth`","B":"`THE TRUTH`","C":"`The Truth`","D":"`the Truth`"},"answer":"A","hint":"capitalize() changes more than just the first letter.","explanation":"capitalize() makes the first character upper case and all the rest lower case, giving The truth.","difficulty":1,"sources":[[2026,"R","91",2]]},{"id":"s0124","chapter":1,"type":"mcq","text":"What is the output of the following code snippet?\n```python\ns='War and Peace by Leo Tolstoy'\nprint(s.partition(\"by\"))\n```","options":{"A":"`('War and Peace ', 'by', ' Leo Tolstoy')`","B":"`['War and Peace ', 'by', ' Leo Tolstoy']`","C":"`('War and Peace ', ' Leo Tolstoy')`","D":"`['War and Peace ', ' Leo Tolstoy']`"},"answer":"A","hint":"partition returns a tuple of three parts including the separator.","explanation":"partition splits at the first 'by' and returns a 3-tuple (before, separator, after).","difficulty":1,"sources":[[2026,"R","91",4]]},{"id":"s0125","chapter":1,"type":"mcq","text":"What will be the output of the following code snippet?\n```python\nt = tuple('tuple')\nt2 = t[2],\nt += t2\nprint(t)\n```","options":{"A":"`('tuple')`","B":"`('tuple','p')`","C":"`('t', 'u', 'p', 'l', 'e', 'p')`","D":"`('t', 'u', 'p', 'l', 'e')`"},"answer":"C","hint":"Note the trailing comma in t2 = t[2],","explanation":"tuple('tuple') gives 5 characters; t[2] is 'p' so t2 = ('p',). t += t2 builds a new tuple with 'p' appended.","difficulty":2,"sources":[[2026,"R","91",6]]},{"id":"s0126","chapter":1,"type":"mcq","text":"Which of the following statements is true about dictionaries in Python?","options":{"A":"A dictionary is an example of sequence datatype.","B":"A dictionary cannot have two elements with same key.","C":"A dictionary cannot have two elements with same value.","D":"The key and value of an element cannot be the same."},"answer":"B","hint":"Think about which part of a dictionary entry must be unique.","explanation":"Keys must be unique; values can repeat, and a dictionary is a mapping, not a sequence.","difficulty":1,"sources":[[2026,"R","91",7]]},{"id":"s0127","chapter":1,"type":"mcq","text":"If L is a list with 6 elements, then which of the following statements will raise an exception?","options":{"A":"`L.pop(1)`","B":"`L.pop(6)`","C":"`L.insert(1,6)`","D":"`L.insert(6, 1)`"},"answer":"B","hint":"Valid indices for 6 elements are 0 to 5; insert is more forgiving than pop.","explanation":"pop(6) raises IndexError as the last index is 5. insert(6, 1) simply appends at the end.","difficulty":2,"sources":[[2026,"R","91",8]]},{"id":"s0128","chapter":2,"type":"mcq","text":"What will be the output of the following code?\n```python\ndef f1(a,b=1):\n    print(a+b,end='-')\nc=f1(1,2)\nprint(c,sep='*')\n```","options":{"A":"`3-2`","B":"`3-2*`","C":"`3-None`","D":"`3*None-`"},"answer":"C","hint":"What does a function without return give back?","explanation":"f1(1,2) prints 3 followed by '-' and returns None. print(c) then prints None (sep is unused for a single item).","difficulty":2,"sources":[[2026,"R","91",9]]},{"id":"s0129","chapter":4,"type":"mcq","text":"Consider the statement given below:\n```python\nf1 = open(\"pqr.dat\", \"__________\")\n```\nWhich of the following is the correct file mode to open the file in read only mode?","options":{"A":"`a`","B":"`rb`","C":"`r+`","D":"`rb+`"},"answer":"B","hint":"Read only means no write or append, and the file is .dat (binary).","explanation":"rb opens a binary file for reading only; a appends, r+ and rb+ allow writing as well.","difficulty":1,"sources":[[2026,"R","91",10]]},{"id":"s0130","chapter":3,"type":"tf","text":"State True or False:\nIn Python, Logical errors can be handled using try...except...finally statement.","options":{"A":"True","B":"False"},"answer":"B","hint":"Exceptions are raised at run time; logic errors do not raise them.","explanation":"Logical errors give wrong results without raising an exception, so try...except cannot handle them.","difficulty":1,"sources":[[2026,"R","91",11]]},{"id":"s0131","chapter":7,"type":"mcq","text":"A table has two candidate keys, one of which is chosen as the primary key. How many alternate keys does this table have?","options":{"A":"0","B":"1","C":"2","D":"3"},"answer":"B","hint":"Alternate keys = candidate keys minus the primary key.","explanation":"2 candidate keys - 1 primary key = 1 alternate key.","difficulty":1,"sources":[[2026,"R","91",12]]},{"id":"s0132","chapter":8,"type":"mcq","text":"Which of the following SQL command can change the degree of the existing relation?","options":{"A":"`DROP TABLE`","B":"`ALTER TABLE`","C":"`UPDATE...SET`","D":"`DELETE`"},"answer":"B","hint":"Degree is the number of columns.","explanation":"ALTER TABLE adds or removes columns, changing the degree.","difficulty":1,"sources":[[2026,"R","91",13]]},{"id":"s0133","chapter":8,"type":"mcq","text":"What will be the output of the query?\n```sql\nSELECT MACHINE_ID, MACHINE_NAME FROM INVENTORY\nWHERE QUANTITY <= 100;\n```","options":{"A":"All columns of INVENTORY table with quantity greater than 100","B":"ID and name of machines with quantity less than 100 from INVENTORY table","C":"All columns of INVENTORY table with quantity greater than or equal to 100","D":"ID and name of machines with quantity less than or equal to 100 from INVENTORY table."},"answer":"D","hint":"Look at the selected columns and the comparison operator.","explanation":"Only MACHINE_ID and MACHINE_NAME are selected, for rows where QUANTITY <= 100.","difficulty":1,"sources":[[2026,"R","91",14]]},{"id":"s0134","chapter":7,"type":"mcq","text":"A relation in MySQL database consists of 2 tuples and 3 attributes. If 2 attributes are deleted and 4 tuples are added, what will be the cardinality of the relation?","options":{"A":"4","B":"5","C":"6","D":"7"},"answer":"C","hint":"Cardinality counts tuples (rows), not attributes.","explanation":"Cardinality = 2 + 4 = 6; deleting attributes changes only the degree.","difficulty":1,"sources":[[2026,"R","91",15]]},{"id":"s0135","chapter":8,"type":"mcq","text":"Which aggregate function in SQL returns the smallest value from a column in a table?","options":{"A":"`MIN()`","B":"`MAX()`","C":"`SMALL()`","D":"`LOWER()`"},"answer":"A","hint":"Which aggregate function name means smallest?","explanation":"MIN() returns the smallest value in a column.","difficulty":1,"sources":[[2026,"R","91",16]]},{"id":"s0136","chapter":6,"type":"mcq","text":"With respect to computer networks, which of the following is the correct expanded form of RJ 45?","options":{"A":"Radio Jockey 45","B":"Registered Jockey 45","C":"Radio Jack 45","D":"Registered Jack 45"},"answer":"D","hint":"It is a type of connector for Ethernet cables.","explanation":"RJ stands for Registered Jack; RJ45 is the Ethernet connector.","difficulty":1,"sources":[[2026,"R","91",17]]},{"id":"s0137","chapter":6,"type":"mcq","text":"Which network device serves as the entry and exit point of a network, as all data coming in or going out of a network must first pass through it in order to use routing paths?","options":{"A":"Modem","B":"Gateway","C":"Switch","D":"Repeater"},"answer":"B","hint":"It connects dissimilar networks.","explanation":"A gateway is the entry/exit point of a network through which all traffic passes.","difficulty":1,"sources":[[2026,"R","91",18]]},{"id":"s0138","chapter":1,"type":"ar","text":"Assertion (A): [1,2,3]+'123' is an invalid expression in Python.\nReason (R): In Python, a list cannot be concatenated with a string.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation for Assertion (A).","B":"Both Assertion (A) and Reason (R) are true and Reason (R) is not the correct explanation for Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"What does + require of both operands for lists?","explanation":"Concatenating a list and a string raises TypeError; R states exactly why A holds.","difficulty":1,"sources":[[2026,"R","91",20]]},{"id":"s0139","chapter":7,"type":"ar","text":"Assertion (A): The PRIMARY KEY constraint in SQL ensures that each value in the column(s) is unique and cannot be NULL.\nReason (R): Candidate keys are not eligible to become a primary key.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation for Assertion (A).","B":"Both Assertion (A) and Reason (R) are true and Reason (R) is not the correct explanation for Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Where does a primary key get chosen from?","explanation":"A is true (unique, NOT NULL). R is false: the primary key is chosen from among the candidate keys.","difficulty":1,"sources":[[2026,"R","91",21]]}]};
